// packages/core/src/messages.ts
export const WireEventSchema = z.discriminatedUnion("type", [
  z.object({ type: z.literal("first_token") }),
  z.object({ type: z.literal("text"), delta: z.string() }),
  z.object({ type: z.literal("usage"), inputTokens: z.number().int().nonnegative(), outputTokens: z.number().int().nonnegative() }),
  z.object({ type: z.literal("done"), stopReason: z.string().nullable() }),
  z.object({ type: z.literal("error"), message: z.string() }),
]);
export type WireEvent = z.infer<typeof WireEventSchema>;

export function encodeSse(event: WireEvent): string {
  return `data: ${JSON.stringify(event)}\n\n`;
}

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function POST(request: Request): Promise<Response> {
  const env = loadServerEnv();
  const parsed = ChatRequestSchema.safeParse(await request.json().catch(() => null));
  if (!parsed.success) return Response.json({ error: "Payload invalido" }, { status: 400 });

  const encoder = new TextEncoder();
  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      const send = (event: WireEvent) => controller.enqueue(encoder.encode(encodeSse(event)));
      try {
        send({ type: "first_token" });
        const upstream = await fetch(`${env.TUTOR_API_URL}/v1/messages`, {
          method: "POST",
          headers: { "content-type": "application/json", "x-api-key": env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01" },
          body: JSON.stringify({ model: env.TUTOR_MODEL, max_tokens: 2048, stream: true, messages: parsed.data.history }),
          signal: request.signal,
        });
        // ... parse do SSE upstream e reenvio com send(...)
      } finally {
        controller.close();
      }
    },
  });

  return new Response(stream, {
    headers: {
      "content-type": "text/plain; charset=utf-8",
      "cache-control": "no-cache, no-transform",
      "x-accel-buffering": "no",
    },
  });
}

function toSessionEvent(event: WireEvent): SessionEvent {
  switch (event.type) {
    case "first_token": return { type: "first_token" };
    case "text":       return { type: "done" }; // texto chegando JA significa que o primeiro token saiu
    case "usage":      return { type: "done" };
    case "done":       return { type: "done" };
    case "error":      return { type: "error", reason: event.message };
  }
}

const session = sessionReducer(state.session, toSessionEvent(action.event));
if (action.event.type === "text") return { ...state, session, text: state.text + action.event.delta };

const baseUrl = process.env["NEXT_PUBLIC_API_URL"] ?? "http://localhost:4000";

export const getLesson = cache(async (lessonId: string): Promise<Lesson | null> => {
  const response = await fetch(`${baseUrl}/lessons/${lessonId}`, { next: { revalidate: 300 } });
  if (response.status === 404) return null;
  if (!response.ok) throw new Error(`API respondeu ${response.status}`);
  return LessonSchema.parse(await response.json());
});

